      "name": "Ramo Verdejante",
      "description": "Videiras e galhos lenhosos se enrolam e se torcem, criando pequenos galhos, folhas e flores na superfície deste braço ou perna protética.\nAtivar 1 (concentrado)\nFrequência uma vez por dia\nEfeito Um galho cresce a partir de sua prótese, florescendo rapidamente e produzindo 1d4 frutos maduros e saborosos. Uma criatura pode colher e comer uma fruta com uma ação de Interagir para recuperar 2d6+5 Pontos de Vida de cura. Os frutos murcham após 10 minutos.",
