      "name": "Escala de Sopro do Dragão",
      "description": "Ativar lançar uma magia\nQuando usada para lançar Breathe Fire ou Chilling Spray, uma escama da garganta de um dragão altera o tipo de dano da magia e a característica correspondente ao tipo de dano e característica do sopro do dragão. Em vez disso, você pode escolher o tipo de dano e a característica correspondente à tradição do dragão, se for diferente.\nEfeito: Escala de Sopro do Dragão\nEspancamento Adamantino ou Fogo\nConspirador mental ou veneno\nFogo ou espírito diabólico\nEspírito empíreo\nForça da fortuna\nFogo com chifres ou veneno\nForça miragem ou mental\nPresságio mental",
