      "name": "Anel da Voraz",
      "description": "Esculpido em madeira de acácia, um anel de voracidade é incrustado com um padrão geométrico. O anel parece ser um Anel de Sustentação. Porém, uma vez investido, ele se funde com você e seus efeitos são ativados imediatamente. Enquanto estiver usando o anel, você precisará do dobro da quantidade normal de comida e bebida para uma criatura do seu tamanho para evitar fome e sede.",
