      "name": "Disco Enredador",
      "description": "Ativar f (concentrar)\nGatilho Você usa o escudo afixado para bloquear com escudo um ataque de arma corpo a corpo\nRequisitos Você é um especialista em Atletismo.\nEste disco de metal do tamanho de uma moeda está inscrito com símbolos misteriosos e montado na superfície interna de um escudo. Quando você ativa o disco, a arma disparadora gruda momentaneamente em seu escudo, permitindo que você tente desarmá-lo de seu portador com um bônus de item de +2. Se você obtiver uma falha crítica neste teste, você obterá uma falha.",
