      "description": "Munição qualquer\nAtivar 1 (concentrado)\nUma substância brilhante, semelhante a alcatrão, que é desagradável ao toque, cobre uma mecha preta. Quando a munição ativada atinge um alvo, ela exala gavinhas que envolvem o alvo, que deve tentar um teste de resistência (fortitude, dc:25). Os efeitos da munição duram até o alvo escapar.\nSucesso Crítico O alvo não é afetado.\nSucesso O alvo sofre Lentidão 1, mas ganha +2 de bônus de circunstância para Escapar do efeito da munição.\nFalha O alvo fica lento 1.\nFalha Crítica O alvo fica Lento 2.",
