      "name": "Troféu Dente de Dragão",
      "description": "Ativar f (concentrar)\nGatilho Você obtém sucesso em um Golpe com a arma afixada.\nEsta presa imponente é gravada com um intrincado arranjo de símbolos, glifos e padrões e fica pendurada em uma tira de couro presa ao punho da arma afixada. Quando você ativa o troféu, sua arma é momentaneamente transformada em uma construção mágica de fúria dracônica. No golpe desencadeado e até o final do seu próximo turno, o tipo de dano da arma afixada muda para o tipo correspondente ao dragão de onde veio a garra. Esta mudança substitui a característica versátil e habilidades semelhantes.\nRequisitos de artesanato Forneça um dente de um dragão adulto ou mais velho.",
