      "name": "Óleo de Medusa Cromático (Moderado)",
      "description": "Ativar 1 (manipular)\nFeito de vários óleos de diferentes tonalidades extraídos de águas-vivas e plantas raras, as camadas de óleo cromático de água-viva se acumulam para formar um arco-íris dentro de seu frasco. Por 10 minutos após consumir óleo de água-viva cromática, você ganha resistência 10 a danos de precisão e dano extra de acertos críticos. Enquanto o efeito durar, você ignora terreno difícil causado ao se mover por espaços apertados que não são apertados o suficiente para forçá-lo a Apertar, e você pode se mover 5 pés (1,5 metros) por rodada quando você Apertar com sucesso (ou 10 pés (3 metros) por rodada em um sucesso crítico). Você também pode rastejar com metade da sua velocidade.\nEfeito: Óleo de Medusa Cromático",
