      "name": "Pena de Jyoti (Maior)",
      "description": "A pena de jyoti é uma pena vermelha e dourada cintilante que parece quase metálica, embora seja delicada e flexível ao toque. Embora a maioria não seja feita de verdadeiras penas de jyoti, já que os forasteiros reclusos evitam visitantes do Universo, a conexão das criaturas com a energia vital deu a esses corações mágicos seu nome.\n• Armadura Você ganha +3 de bônus de item em testes de resistência contra efeitos de morte e energia do vazio.\n• Arma A arma possui a runa Vitalizante enquanto a pena está afixada.\nEfeito: Pena de Jyoti – Armadura\nEfeito: Pena de Jyoti – Arma\nAtivar lançar uma magia\nEfeito Você lança Estabilizar.\nAtivar lançar uma magia\nFrequência uma vez por dia\nEfeito Você lança o Farol Vital do 5º Rank.\nAtivar lançar uma magia\nFrequência uma vez por dia\nEfeito que você lança Healing Well",
